window.products.push({"id":671062,"name":"Journey's Edge 72-W0627 Indoor/Outdoor Projection Weather Center with Clock with 2 Function Alarm","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/619YPJy48eL._AC_SL1000_.jpg","description":"With the Indoor/Outdoor Projection Weather Center by Journey’s Edge you’ll know with accuracy what the weather outside is from the comfort of your home. This incredible display shows the time, temperature, date and humidity and the projector feature illuminates the time and temperature onto your ceiling or wall. Don't get caught unprepared in the elements. Get the Indoor/Outdoor Projection Weather Center and know what to expect before you leave the house!","images":["https://m.media-amazon.com/images/I/619YPJy48eL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Journey's Edge","source_asin":"B004SQNLVW","category_path":"Home & Kitchen"},"sku":"BM-671062","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B004SQNLVW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B004SQNLVW","price_pending":true,"merchant_ready":false});
